// SVG wallpapers for solid and gradient wallpaper specs.

export function wallpaperSvg(spec, w = 3840, h = 2160) {
    const head = `<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by Paletka -->
<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">`;
    switch (spec?.type) {
    case 'solid':
        return `${head}
  <rect width="${w}" height="${h}" fill="${spec.color}"/>
</svg>
`;
    case 'gradient':
        return `${head}
  <defs>
    <linearGradient id="g" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="${spec.from}"/>
      <stop offset="1" stop-color="${spec.to}"/>
    </linearGradient>
  </defs>
  <rect width="${w}" height="${h}" fill="url(#g)"/>
</svg>
`;
    default:
        return null;
    }
}
